export type ParsedSyncLoanInstruction<
  TProgram extends string = typeof RECEIVABLES_POOL_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    pool: TAccountMetas[0];
    loan: TAccountMetas[1];
    exposure: TAccountMetas[2];
    /** vault's owner below. */
    poolAuthority: TAccountMetas[3];
    quoteVault: TAccountMetas[4];
    collateralVault: TAccountMetas[5];
    loanProceeds: TAccountMetas[6];
    /** The borrower's USDC account, for what is left once nothing is owed. */
    borrowerQuote: TAccountMetas[7];
    quoteTokenProgram: TAccountMetas[8];
    collateralTokenProgram: TAccountMetas[9];
    quoteMint: TAccountMetas[10];
    collateralMint: TAccountMetas[11];
  };
  data: SyncLoanInstructionData;
};

export function parseSyncLoanInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSyncLoanInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      pool: getNextAccount(),
      loan: getNextAccount(),
      exposure: getNextAccount(),
      poolAuthority: getNextAccount(),
      quoteVault: getNextAccount(),
      collateralVault: getNextAccount(),
      loanProceeds: getNextAccount(),
      borrowerQuote: getNextAccount(),
      quoteTokenProgram: getNextAccount(),
      collateralTokenProgram: getNextAccount(),
      quoteMint: getNextAccount(),
      collateralMint: getNextAccount(),
    },
    data: getSyncLoanInstructionDataDecoder().decode(instruction.data),
  };
}
